// Exercise explicitly configured public services without dispatching external media work.
test.beforeEach(async({modelOrkas:orkas})=>{
 await orkas.electronApp!.evaluate((_electron:any,root:string)=>{
  const load=(process as any).mainModule.require.bind((process as any).mainModule),auth=load(root+'/features/auth.ts');
  auth.saveImageProfiles([{id:'lifecycle-image',provider:'openai',model:'gpt-image-2',apiKey:'fixture-unused-image',label:'Local image service',createdAt:1}]);
  auth.saveVideoProfiles([{id:'lifecycle-video',provider:'doubao',model:'doubao-seedance-2-0-260128',apiKey:'fixture-unused-video',label:'Local video service',createdAt:1}]);
  auth.saveTtsProfiles([{id:'lifecycle-voice',provider:'openai',model:'tts-1',baseUrl:'https://speech.fixture/v1',apiKey:'fixture-unused-voice',voice:'alloy',label:'Local speech service',createdAt:1}]);
  const image=load(root+'/features/image_gen.ts'),video=load(root+'/features/video_gen.ts'),tts=load(root+'/features/tts.ts'),originals=[image.generateImage,video.generateVideo,tts.generateSpeech];
  const fixture={calls:0,restore:()=>{[image.generateImage,video.generateVideo,tts.generateSpeech]=originals;}};
  (globalThis as any).__contentLifecycleMedia=fixture;
  image.generateImage=video.generateVideo=tts.generateSpeech=async()=>{fixture.calls++;throw Error('Unexpected external media generation in the controlled lifecycle fixture');};
 },path.resolve(__dirname,'../../src/main'));
});
test.afterEach(async({modelOrkas:orkas})=>{
 const calls=await orkas.electronApp?.evaluate(()=>{const fixture=(globalThis as any).__contentLifecycleMedia;if(!fixture)return null;fixture.restore();return fixture.calls;});
 expect(calls).toBe(0);
});

