async function showRecords(frame:any,kind?:string){if(kind&&await frame.locator('#nav-'+kind).getAttribute('aria-selected')!=='true')await frame.locator('#nav-'+kind).click();await frame.locator('#records').scrollIntoViewIfNeeded();}
// Seed pre-reset legacy records explicitly; Reset never creates a history record.
async function legacyDraft(frame:any){
 const brief=await frame.locator('#brief').inputValue(),kind=await frame.locator('[data-kind][aria-selected="true"]').getAttribute('data-kind');
 // Re-selecting the current media tab flushes pending settings/material saves
 // through the real UI before the legacy seed takes ownership of the index.
 await frame.locator('#nav-'+kind).click();await expect(frame.locator('#brief')).toBeEnabled();
 await expect.poll(async()=>(await index(frame))?.drafts?.[kind]?.brief).toBe(brief);
 const id=await frame.locator('body').evaluate(async(_el:any,kind:string)=>{const api=(window as any).orkasApp,state=(await api.storage.get({key:'content-index-v1',scope:'cloud'})).value,w={...state.drafts[kind],id:crypto.randomUUID(),createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};await api.appFiles.writeText({path:'works/'+w.id+'.json',text:JSON.stringify(w),scope:'cloud'});state.works.unshift({id:w.id,title:w.brief.trim().slice(0,160),kind,updatedAt:w.updatedAt,status:'',assetIds:w.assetIds,resultAssetIds:[]});delete state.drafts[kind];await api.storage.set({key:'content-index-v1',value:state,scope:'cloud'});return w.id;},kind);
 const body=await frame.locator('body').elementHandle(),native=await body!.ownerFrame();await native!.goto(native!.url());await body!.dispose();await frame.locator('#nav-'+kind).click();await restoreRecord(frame,id);await frame.locator('#brief').fill(brief);await expect(frame.locator('#save-state')).toHaveText('已保存');
}
async function resultAction(frame:any,name:string,label:string){await expandRecord(frame);const file=frame.locator('.result-file').filter({hasText:name}).last();await file.hover();await file.locator('.result-menu-trigger').click();await frame.locator('#record-menu').getByRole('menuitem',{name:label,exact:true}).click();}
async function recordAction(frame:any,label:string,id?:string){await recordMenu(frame,id);await frame.locator('#record-menu').getByRole('menuitem',{name:label,exact:true}).click();}
async function previewResult(frame:any,name:string){
 await expandRecord(frame);
 const file=frame.locator('.result-file').filter({hasText:name}).last(),more=frame.locator('.result-tools summary');
 // Opening a record loads its files asynchronously. Absence before that render
 // does not establish that the target belongs to the optional More files group.
 await expect.poll(async()=>await file.isVisible()||await more.isVisible()).toBe(true);
 if(!await file.isVisible())await more.click();
 await expect(file).toBeVisible();await file.locator('.attachment-preview').click();await expect(frame.locator('#media-preview')).toBeVisible();
}
async function restoreRecord(frame:any,id?:string){
 const target=id||await frame.locator('.history-row').first().getAttribute('data-id'),source=await work(frame,target);
 const restored=async()=>(await index(frame))?.drafts?.[source.kind];
 await recordAction(frame,'编辑',target);
 // The reset button can already be enabled while editRecord awaits its source.
 // Wait for confirmation or this record's durable edit draft before proceeding.
 await expect.poll(async()=>await frame.locator('#confirm').isVisible()?'confirm':(await restored())?.sourceWorkId===target?'restored':'loading').not.toBe('loading');
 if(await frame.locator('#confirm').isVisible())await frame.locator('#confirm [value="confirm"]').click();
 await expect.poll(restored).toMatchObject({sourceWorkId:target,brief:source.brief,settings:source.settings,assetIds:source.assetIds});
 await expect(frame.locator('#reset-work')).toBeEnabled();
}

