async function transferFiles(frame:any,files:{name:string;base64:string}[],type='drop',target='#brief'){
 await expect(frame.locator(target)).toBeVisible();
 return frame.locator(target).evaluate((element:any,{files,type}:any)=>{const transfer=new DataTransfer();for(const f of files){const bytes=Uint8Array.from(atob(f.base64),c=>c.charCodeAt(0));transfer.items.add(new File([bytes],f.name));}const event=type==='paste'?new ClipboardEvent('paste',{bubbles:true,cancelable:true,clipboardData:transfer}):new DragEvent('drop',{bubbles:true,cancelable:true,dataTransfer:transfer});element.dispatchEvent(event);return event.defaultPrevented;},{files,type});
}
