async function reset(frame:any){
 await expect(frame.locator('#reset-work')).toBeEnabled();
 const occupied=!!(await frame.locator('#brief').inputValue()).trim()||await frame.locator('#selected-assets .chat-attach-chip').count()>0;
 await frame.locator('#reset-work').click();
 if(occupied){await expect(frame.locator('#confirm')).toBeVisible();await frame.locator('#confirm [value="confirm"]').click();}
}

