  const ratio=await frame.locator(selector).first().evaluate(el=>{
   const canvas=document.createElement('canvas');canvas.width=canvas.height=1;const ctx=canvas.getContext('2d',{willReadFrequently:true})!;
   const rgba=(value:string)=>{ctx.clearRect(0,0,1,1);ctx.fillStyle=value;ctx.fillRect(0,0,1,1);const n=ctx.getImageData(0,0,1,1).data;return[n[0],n[1],n[2],n[3]/255];};
   const blend=(fg:number[],bg:number[])=>fg.slice(0,3).map((n,i)=>n*fg[3]+bg[i]*(1-fg[3]));
   let bg=[255,255,255];const parents:Element[]=[];for(let p:Element|null=el;p;p=p.parentElement)parents.unshift(p);
   for(const p of parents)bg=blend(rgba(getComputedStyle(p).backgroundColor),bg);
   const fg=blend(rgba(getComputedStyle(el).color),bg),luminance=(c:number[])=>c.map(n=>{n/=255;return n<=.04045?n/12.92:((n+.055)/1.055)**2.4;}).reduce((s,n,i)=>s+n*[.2126,.7152,.0722][i],0);
   const a=luminance(fg),b=luminance(bg);return(Math.max(a,b)+.05)/(Math.min(a,b)+.05);
  });expect(ratio,selector+' must remain readable').toBeGreaterThanOrEqual(4.5);
