test('keeps a delayed automatic file receipt with its original record without overwriting a newer draft',async({modelOrkas:orkas})=>{
 const{preview,frame}=await open(orkas);
 await orkas.electronApp!.evaluate(async(_electron,module)=>{const runtime=((globalThis as any).__contentOutputFixture?.load(module)||(process as any).mainModule.require(module)).runtime,original=runtime.execute;let release!:()=>void;const gate=new Promise<void>(resolve=>{release=resolve;}),state={ready:false,release,restore:()=>{release();runtime.execute=original;}};runtime.execute=async function(...args:any[]){if(args[1]==='tasks.output'){state.ready=true;await gate;}return original.apply(this,args);};(globalThis as any).__delayedArchive=state;},path.resolve(__dirname,'../../src/main/features/web_apps/host.ts'));
await frame.locator('#brief').fill('Original delayed result.');await stageOutputs(orkas,[{name:'result.png',base64:png}]);orkas.setModelTextReplies(['Done.']);await frame.locator('#submit').click();await expect.poll(async()=>(await index(frame))?.works[0]?.status,{timeout:60000}).toBe('completed');const original=(await index(frame)).works[0],requestId=(await work(frame,original.id)).jobs[0].requestId;await output(orkas,requestId,'result.png',png);

 try{await refreshRecord(frame);await expect.poll(()=>orkas.electronApp!.evaluate(()=>(globalThis as any).__delayedArchive.ready)).toBe(true);await frame.locator('#brief').fill('Keep this next draft.');await expect.poll(async()=>(await index(frame)).drafts.image.brief).toBe('Keep this next draft.');await orkas.electronApp!.evaluate(()=>(globalThis as any).__delayedArchive.release());await expect.poll(async()=>(await work(frame,original.id)).results.some((r:any)=>r.outputId)).toBe(true);await expect(frame.locator('#brief')).toHaveValue('Keep this next draft.');expect(orkas.modelRequests).toHaveLength(1);}finally{await orkas.electronApp!.evaluate(()=>(globalThis as any).__delayedArchive.restore());await orkas.closePreview(preview);}
});

for(const [appId,appName,key] of [['builtin-content-workbench','content_workbench','content-index-v1'],['builtin-product-listing','product_listing','content-index-v1']]){
 test('retains local lifecycle, failure recovery and live registered languages: '+appName,async({modelOrkas:orkas},info)=>{
  const page=orkas.page!;
  await page.evaluate(()=>(window as any).setLang('zh'));await openSidebarEntry(page,'#apps-btn');
  const show=async(ready=true)=>{const preview=await orkas.openPreview(()=>page.locator(`.app-card[data-app-id="${appId}"]`).click());const host=preview.frameLocator('.saved-app-viewer-frame');if(appName==='product_listing')await host.locator('button[data-view="creative"]').click();const frame=appName==='content_workbench'?host:host.frameLocator('#media-workspace');if(ready)await expect(frame.locator('#brief')).toBeEnabled();return{preview,frame};};
  let {preview,frame}=await show();
  await frame.locator('#brief').fill('Preserve this authored request.');await legacyDraft(frame);
  await expect(frame.locator('#save-state')).toHaveText('已保存');
  const locales=await orkas.electronApp!.evaluate(async(_electron:any,module:string)=>((globalThis as any).__contentOutputFixture?.load(module)||(process as any).mainModule.require(module)).SUPPORTED_LANGS,path.resolve(__dirname,'../../src/main/i18n.ts'));
  for(const language of locales){
   await page.evaluate((language:string)=>(window as any).setLang(language),language);
   await frame.locator('body').evaluate(()=>window.dispatchEvent(new Event('focus')));
   await expect(frame.locator('html')).toHaveAttribute('lang',language);
   const labels=await frame.locator('body').evaluate((_element:any,appName:string)=>{const w=window as any,dict=w.ContentLocales[document.documentElement.lang];return{expected:dict.title,actual:document.title,saved:dict.saved,actualSaved:document.getElementById('save-state').textContent,missing:[...document.querySelectorAll('[data-t]')].filter((el:any)=>!['page-title','generate'].includes(el.id)&&el.textContent!==dict[el.dataset.t]).map((el:any)=>({id:el.id,key:el.dataset.t,actual:el.textContent,expected:dict[el.dataset.t]}))};},appName);
   // Page title and Generate are contextual labels, asserted through their owning journeys.
   expect(labels.actual).toBe(labels.expected);expect(labels.missing).toEqual([]);expect(labels.actualSaved).toBe(labels.saved);
   await expect(frame.locator('html')).toHaveAttribute('dir',language==='ar'?'rtl':'ltr');
   if(['en','ar'].includes(language))await preview.screenshot({path:info.outputPath(appName+'-'+language+'.png')});
  }
  await expect(frame.locator('#brief')).toHaveValue('Preserve this authored request.');
  const original=(await frame.locator('body').evaluate(async(_el:any,key:string)=>(await (window as any).orkasApp.storage.get({key,scope:'cloud'})).value,key));
  // A real SDK save failure preserves the authored record and supports recovery.
  await orkas.electronApp!.evaluate(async(_electron:any,{module,appName}:{module:string;appName:string})=>{const runtime=((globalThis as any).__contentOutputFixture?.load(module)||(process as any).mainModule.require(module)).runtime,original=runtime.execute;runtime.execute=async function(...args:any[]){if(args[1]==='storage.set'){runtime.execute=original;throw new (((globalThis as any).__contentOutputFixture?.load(module.replace('host.ts','runtime.ts'))||(process as any).mainModule.require(module.replace('host.ts','runtime.ts'))).AppError)('E_DATA');}return original.apply(this,args);};},{module:path.resolve(__dirname,'../../src/main/features/web_apps/host.ts'),appName});
  await reset(frame);await expect(frame.locator('#notice')).not.toBeEmpty();
  for(const language of ['en','zh']){
   await page.evaluate((language:string)=>(window as any).setLang(language),language);await frame.locator('body').evaluate(()=>window.dispatchEvent(new Event('focus')));await expect(frame.locator('html')).toHaveAttribute('lang',language);
   const notice=await frame.locator('body').evaluate((_el:any,appName:string)=>{const w=window as any,lang=document.documentElement.lang,expected=w.ContentLocales[lang].error;return{expected,actual:document.getElementById('notice').textContent};},appName);expect(notice.actual).toBe(notice.expected);
  }
  expect(await frame.locator('body').evaluate(async(_el:any,key:string)=>(await (window as any).orkasApp.storage.get({key,scope:'cloud'})).value,key)).toEqual(original);
  await frame.locator('body').evaluate(async(_el:any,key:string)=>{await (window as any).orkasApp.storage.set({key,scope:'cloud',value:{schemaVersion:900}});},key);
  await orkas.closePreview(preview);
  ({preview,frame}=await show(false));await expect(frame.locator('#notice')).not.toBeEmpty();
  // A failed read must not silently replace the damaged record; repair and reopen.
  expect(await frame.locator('body').evaluate(async(_el:any,key:string)=>(await (window as any).orkasApp.storage.get({key,scope:'cloud'})).value,key)).toEqual({schemaVersion:900});
  await frame.locator('body').evaluate(async(_el:any,args:any)=>{await (window as any).orkasApp.storage.set({key:args.key,scope:'cloud',value:args.original});},{key,original});
  await orkas.closePreview(preview);({preview,frame}=await show());
  await showRecords(frame);await expect(frame.locator('#works-list')).toContainText('Preserve this authored request.');
  await orkas.closePreview(preview);
 });
}

test('reopens an early app record without a page error, task replay or deletion of its original conversation',async({modelOrkas:orkas})=>{
 orkas.setModelTextReplies(['Legacy saved reply.']);
 const cid=await orkas.electronApp!.evaluate(async(_electron:any,base:string)=>{const load=((globalThis as any).__contentOutputFixture?.load||(process as any).mainModule.require.bind((process as any).mainModule)),conv=await load(base+'/features/chats.ts').createConversation('account-e2e',{title:'Legacy poster'});await load(base+'/features/group_chat/index.ts').send({userId:'account-e2e',cid:conv.conversation_id,text:'Original legacy request',forceTo:['commander']});return conv.conversation_id;},path.resolve(__dirname,'../../src/main'));
 await expect.poll(()=>orkas.modelRequests.length).toBe(1);
 await expect.poll(()=>orkas.electronApp!.evaluate(async(_electron:any,args:any)=>(process as any).mainModule.require(args.bus).isQuiescent('account-e2e',args.cid),{bus:path.resolve(__dirname,'../../src/main/features/group_chat/bus.ts'),cid})).toBe(true);
 // A legacy installation already has its records before the app opens. Seed
 // that persisted state before startup; writing it through a live frame races
 // the initial service selection's debounced draft save and loses the seed.
 await orkas.electronApp!.evaluate(async(_electron:any,args:any)=>{
  const load=(process as any).mainModule.require.bind((process as any).mainModule);
  const hash=(s:string)=>load('node:crypto').createHash('sha256').update(s).digest('hex');
  const key=hash(JSON.stringify(['saved','builtin-content-workbench']));
  const paths=load(args.base+'/paths.ts'),storage=load(args.base+'/storage.ts'),join=load('node:path').join;
  const root=paths.webAppSandboxRoot('account-e2e',key,'cloud'),m=load(args.model);
  const w={...m.draft('image','zh'),id:'legacy-page-work',title:'Legacy poster',brief:'Original legacy request',createdAt:new Date().toISOString(),updatedAt:new Date().toISOString(),jobs:[{requestId:'legacy-page',status:'running',text:'',outputs:[]}]};
  const state=m.readIndex(null);
  state.works.push({id:w.id,title:w.title,kind:w.kind,status:'running',updatedAt:w.updatedAt,assetIds:[],resultAssetIds:[]});
  await storage.writeJson(join(root,'tasks',hash('legacy-page')+'.json'),{version:1,requestId:'legacy-page',fingerprint:'a'.repeat(64),cid:args.cid,phase:'submitted',createdAt:new Date().toISOString()});
  await storage.writeJson(join(root,'files','works',w.id+'.json'),w);
  await storage.writeJson(paths.webAppDataFile('account-e2e',key,'cloud'),{version:1,entries:{'content-index-v1':state}});
 },{base:path.resolve(__dirname,'../../src/main'),model:path.resolve(__dirname,'../../resources/builtin/apps/builtin-content-workbench/model.js'),cid});
 const{preview,frame}=await open(orkas);
 await expect.poll(async()=>(await index(frame))?.works[0]?.status,{timeout:15000}).toBe('completed');
 await expect.poll(async()=>(await work(frame,'legacy-page-work')).results.length).toBe(1);
 await expect(frame.locator('#notice')).toBeHidden();await previewResult(frame,'reply.txt');await expect(frame.locator('#media-content pre')).toHaveText('Legacy saved reply.');
 expect(await orkas.electronApp!.evaluate(async(_electron:any,args:any)=>(await (process as any).mainModule.require(args.chats).getConversationMetadata('account-e2e',args.cid))?.kind,{chats:path.resolve(__dirname,'../../src/main/features/chats.ts'),cid})).toBe('normal');
 expect(orkas.modelRequests).toHaveLength(1);await orkas.closePreview(preview);
});


